import { useEffect, useMemo, useState, type ChangeEvent, type FormEvent, type ReactNode } from "react";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { Link, Route, Switch, useLocation, useParams } from "wouter";
import {
  Activity, AlertCircle, ArrowDownAZ, ArrowUpAZ, Calculator, Check, ChevronLeft, ChevronRight,
  Clipboard, Copy, Database, Edit3, Filter, Loader2, MoreHorizontal, Network, Pencil,
  Plus, RefreshCw, Search, Server, Settings2, ShieldCheck, Trash2, Wifi, X,
} from "lucide-react";
import { ErrorBoundary } from "@/components/error-boundary";
import { Toaster } from "@/components/ui/toaster";
import { TooltipProvider } from "@/components/ui/tooltip";
import { Layout } from "@/components/layout";
import { api, type AvailabilityWindows, type Device, type MonitoringHistory, type MonitoringIncident, type NotificationDelivery, type PingResult, type SavedConfiguration, type Settings } from "@/lib/api";
import NotFound from "@/pages/not-found";

const queryClient = new QueryClient();
const DEVICE_TYPES = ["Physical Server", "Virtual Machine", "Container", "Router", "Switch", "Firewall", "Storage", "Wireless", "Other"];
const DEVICE_VENDORS = ["Cisco", "Juniper", "Arista", "Palo Alto", "Fortinet", "Dell", "Supermicro", "HPE", "VMware", "Proxmox", "Linux", "Other"];
const CONFIG_VENDORS = ["Cisco IOS / IOS-XE", "Cisco NX-OS", "Juniper Junos", "Arista EOS"];
const CONFIG_TYPES = ["SNMPv3", "Syslog", "NTP", "NetFlow / IPFIX"];
const cls = (...parts: (string | false | undefined)[]) => parts.filter(Boolean).join(" ");

function Button({ children, variant = "primary", className = "", ...props }: React.ButtonHTMLAttributes<HTMLButtonElement> & { variant?: "primary" | "ghost" | "danger" | "secondary" }) {
  return <button className={cls("inline-flex items-center justify-center gap-2 rounded-md px-3.5 py-2 text-xs font-bold transition-all disabled:cursor-not-allowed disabled:opacity-50", variant === "primary" && "bg-primary text-primary-foreground hover:brightness-110", variant === "secondary" && "bg-secondary text-secondary-foreground hover:bg-secondary/70", variant === "ghost" && "text-muted-foreground hover:bg-secondary hover:text-foreground", variant === "danger" && "border border-destructive/30 text-destructive hover:bg-destructive/10", className)} {...props}>{children}</button>;
}
function Input({ className = "", ...props }: React.InputHTMLAttributes<HTMLInputElement>) { return <input className={cls("h-10 w-full rounded-md border border-input bg-background px-3 text-sm outline-none transition-colors placeholder:text-muted-foreground focus:border-primary focus:ring-2 focus:ring-primary/15", className)} {...props} />; }
function Select({ className = "", ...props }: React.SelectHTMLAttributes<HTMLSelectElement>) { return <select className={cls("h-10 w-full rounded-md border border-input bg-background px-3 text-sm outline-none focus:border-primary focus:ring-2 focus:ring-primary/15", className)} {...props} />; }
function Textarea({ className = "", ...props }: React.TextareaHTMLAttributes<HTMLTextAreaElement>) { return <textarea className={cls("min-h-[92px] w-full resize-y rounded-md border border-input bg-background px-3 py-2 text-sm outline-none focus:border-primary focus:ring-2 focus:ring-primary/15", className)} {...props} />; }
function Label({ children }: { children: ReactNode }) { return <label className="mb-1.5 block text-[11px] font-bold uppercase tracking-[.08em] text-muted-foreground">{children}</label>; }
function Card({ children, className = "" }: { children: ReactNode; className?: string }) { return <section className={cls("rounded-lg border border-card-border bg-card", className)}>{children}</section>; }
function PageTitle({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: ReactNode }) {
  return <div className="mb-8 flex flex-col justify-between gap-5 sm:flex-row sm:items-end animate-rise"><div><p className="mono mb-2 text-[10px] uppercase tracking-[.2em] text-primary">{eyebrow}</p><h1 className="text-2xl font-extrabold tracking-tight sm:text-3xl">{title}</h1><p className="mt-2 max-w-xl text-sm text-muted-foreground">{description}</p></div>{action}</div>;
}
function Status({ status }: { status?: string }) {
  const good = status === "online"; const bad = status === "offline";
  return <span className={cls("inline-flex items-center gap-1.5 text-[11px] font-bold capitalize", good ? "text-primary" : bad ? "text-destructive" : "text-muted-foreground")}><span className={cls("size-1.5 rounded-full", good ? "bg-primary shadow-[0_0_6px_hsl(var(--primary))]" : bad ? "bg-destructive" : "bg-muted-foreground")} />{status || "unknown"}</span>;
}
function Loading() { return <div className="space-y-3">{[1, 2, 3].map((item) => <div key={item} className="h-14 animate-pulse rounded-md bg-secondary/60" />)}</div>; }
function ErrorState({ onRetry }: { onRetry: () => void }) {
  return <div className="rounded-lg border border-destructive/30 bg-destructive/5 p-8 text-center"><AlertCircle className="mx-auto text-destructive" size={24} /><p className="mt-3 font-bold">Unable to reach the LabOps API</p><p className="mt-1 text-sm text-muted-foreground">Check the API server and try again.</p><Button variant="danger" className="mt-4" onClick={onRetry}><RefreshCw size={14} />Retry</Button></div>;
}
function Empty({ text, action }: { text: string; action?: ReactNode }) { return <div className="p-8 text-center text-sm text-muted-foreground"><p>{text}</p>{action}</div>; }
function Detail({ label, value, mono = false }: { label: string; value?: string; mono?: boolean }) { return <div><p className="text-[11px] text-muted-foreground">{label}</p><p className={cls("mt-1 text-sm font-semibold", mono && "mono")}>{value || "—"}</p></div>; }
function SectionHeader({ title, text }: { title: string; text: string }) { return <div className="border-b border-card-border px-5 py-4"><h2 className="font-bold">{title}</h2><p className="mt-1 text-xs text-muted-foreground">{text}</p></div>; }
function formatDuration(seconds?: number | null) { if (seconds == null) return "Ongoing"; if (seconds < 60) return `${seconds}s`; if (seconds < 3600) return `${Math.round(seconds / 60)}m`; return `${Math.round(seconds / 3600)}h`; }
function AvailabilityCard({ label, value }: { label: string; value?: { percentage: number | null; observedChecks: number } }) { return <Card className="p-5"><p className="text-xs text-muted-foreground">{label}</p><p className="mono mt-3 text-2xl">{value?.percentage == null ? "—" : `${value.percentage}%`}</p><p className="mt-1 text-[10px] text-muted-foreground">{value?.observedChecks ?? 0} observed checks</p></Card>; }
function IncidentRow({ incident, deviceName }: { incident: MonitoringIncident; deviceName?: string }) { return <div className="flex flex-col gap-2 px-5 py-4 sm:flex-row sm:items-center sm:justify-between"><div>{deviceName && <span className="mr-3 font-bold">{deviceName}</span>}<span className={cls("rounded px-2 py-1 text-[10px] font-bold uppercase", incident.status === "open" ? "bg-destructive/10 text-destructive" : "bg-primary/10 text-primary")}>{incident.status}</span><p className="mt-2 text-xs text-muted-foreground">{incident.errorMessage || (incident.status === "open" ? "Sustained outage in progress." : `Resolved by ${incident.resolutionReason || "recovery"}.`)}</p></div><div className="mono text-[10px] text-muted-foreground">{new Date(incident.startedAt).toLocaleString()} · {formatDuration(incident.durationSeconds)}</div></div>; }
function Modal({ children, onClose }: { children: ReactNode; onClose: () => void }) { return <div className="fixed inset-0 z-40 grid place-items-center bg-black/60 p-4"><div className="max-h-[92dvh] w-full max-w-2xl overflow-auto rounded-xl border border-card-border bg-card p-6 shadow-2xl">{children}</div></div>; }

function Dashboard() {
  const [summary, setSummary] = useState<Record<string, number | null>>({});
  const [recent, setRecent] = useState<Device[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);
  const [checking, setChecking] = useState(false);
  const load = () => { setLoading(true); setError(false); Promise.all([api.summary(), api.recent()]).then(([nextSummary, nextRecent]) => { setSummary(nextSummary); setRecent(nextRecent); }).catch(() => setError(true)).finally(() => setLoading(false)); };
  useEffect(load, []);
  const check = () => { setChecking(true); api.checkMonitored().then(load).catch(() => undefined).finally(() => setChecking(false)); };
  return <><PageTitle eyebrow="Operations overview" title="Dashboard" description="A clear read on your home lab, without the noise of an enterprise NOC." action={<Button onClick={check} disabled={checking}><RefreshCw size={14} className={checking ? "animate-spin" : ""} />Check monitored</Button>} />{error ? <ErrorState onRetry={load} /> : loading ? <Loading /> : <div className="space-y-6 animate-rise">
    <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-6"><Metric label="Total devices" value={summary.totalDevices ?? 0} icon={Database} /><Metric label="Online" value={summary.onlineDevices ?? 0} icon={Wifi} tone="good" /><Metric label="Offline" value={summary.offlineDevices ?? 0} icon={AlertCircle} tone="bad" /><Metric label="Unknown" value={summary.unknownDevices ?? 0} icon={Activity} /><Metric label="Open incidents" value={summary.openIncidents ?? 0} icon={AlertCircle} tone={summary.openIncidents ? "bad" : "good"} /><Metric label="24h availability" value={summary.availability24h == null ? "—" : `${summary.availability24h}%`} icon={ShieldCheck} tone="good" /></div>
    <Card><div className="flex items-center justify-between border-b border-card-border px-5 py-4"><div><h2 className="font-bold">Recent device status</h2><p className="mt-1 text-xs text-muted-foreground">Current reachability, not historical metrics.</p></div><Link href="/devices" className="text-xs font-bold text-primary hover:underline">View inventory</Link></div><div className="overflow-x-auto"><table className="w-full min-w-[800px] text-left"><thead className="bg-secondary/40"><tr className="mono text-[10px] uppercase tracking-wider text-muted-foreground"><th className="px-5 py-3 font-normal">Status</th><th className="px-4 py-3 font-normal">Hostname</th><th className="px-4 py-3 font-normal">IP address</th><th className="px-4 py-3 font-normal">Device type</th><th className="px-4 py-3 font-normal">Vendor</th><th className="px-4 py-3 font-normal">Model</th><th className="px-5 py-3 font-normal">Last checked</th></tr></thead><tbody className="divide-y divide-card-border">{recent.length ? recent.map((device) => <tr key={device.id} className="hover:bg-secondary/25"><td className="px-5 py-4"><Status status={device.lastStatus} /></td><td className="px-4 py-4"><Link href={`/devices/${device.id}`} className="font-bold hover:text-primary">{device.hostname}</Link></td><td className="mono px-4 py-4 text-xs text-muted-foreground">{device.managementIp}</td><td className="px-4 py-4 text-xs">{device.deviceType}</td><td className="px-4 py-4 text-xs text-muted-foreground">{device.vendor}</td><td className="px-4 py-4 text-xs text-muted-foreground">{device.model || "—"}</td><td className="px-5 py-4 text-xs text-muted-foreground">{device.lastCheckedAt ? new Date(device.lastCheckedAt).toLocaleString() : "Not checked"}</td></tr>) : <tr><td colSpan={7}><Empty text="No devices yet." /></td></tr>}</tbody></table></div></Card>
    <div className="rounded-lg border border-primary/20 bg-primary/5 p-5"><div className="flex gap-4"><ShieldCheck className="mt-0.5 shrink-0 text-primary" size={20} /><div><p className="text-sm font-bold">Automated health, manual control</p><p className="mt-1 text-xs leading-5 text-muted-foreground">Enabled devices are polled in the background. Manual Ping Now remains available for immediate checks.</p></div></div></div>
  </div>}</>;
}
function Metric({ label, value, icon: Icon, tone }: { label: string; value: number | string; icon: typeof Database; tone?: "good" | "bad" }) { const magnitude = typeof value === "number" ? value : Number.parseFloat(value) || 0; return <Card className="p-5"><div className="flex items-start justify-between"><p className="text-xs text-muted-foreground">{label}</p><Icon size={17} className={tone === "good" ? "text-primary" : tone === "bad" ? "text-destructive" : "text-muted-foreground"} /></div><p className="mono mt-5 text-3xl">{value}</p><div className="mt-3 h-1 rounded-full bg-secondary"><div className={cls("h-1 rounded-full", tone === "bad" ? "bg-destructive" : "bg-primary")} style={{ width: `${Math.min(magnitude * 12 + 8, 100)}%` }} /></div></Card>; }

type DeviceFormProps = { initial?: Device; onClose: () => void; onSaved: () => void };
function DeviceForm({ initial, onClose, onSaved }: DeviceFormProps) {
  const [form, setForm] = useState<Partial<Device>>(initial ?? { hostname: "", managementIp: "", deviceType: "Other", vendor: "Other", model: "", operatingSystem: "", location: "", serialNumber: "", notes: "", monitoringEnabled: true, maintenanceMode: false, monitoringIntervalSeconds: 60 });
  const [saving, setSaving] = useState(false);
  const update = (key: keyof Device) => (event: ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => setForm({ ...form, [key]: event.target.value });
  const submit = (event: FormEvent) => { event.preventDefault(); setSaving(true); const task = initial ? api.updateDevice(initial.id, form) : api.createDevice({ ...form, lastStatus: "unknown" }); task.then(onSaved).catch(() => undefined).finally(() => setSaving(false)); };
  return <Modal onClose={onClose}><form onSubmit={submit}><div className="mb-6 flex justify-between"><div><p className="mono text-[10px] uppercase tracking-[.18em] text-primary">{initial ? "Edit record" : "New record"}</p><h2 className="mt-1 text-xl font-extrabold">{initial ? initial.hostname : "Add device"}</h2></div><Button type="button" variant="ghost" onClick={onClose}><X size={18} /></Button></div><div className="grid gap-4 sm:grid-cols-2"><div><Label>Hostname *</Label><Input required value={form.hostname ?? ""} onChange={update("hostname")} /></div><div><Label>Management IP *</Label><Input required value={form.managementIp ?? ""} onChange={update("managementIp")} /></div><div><Label>Device type</Label><Select value={form.deviceType} onChange={update("deviceType")}>{DEVICE_TYPES.map((item) => <option key={item}>{item}</option>)}</Select></div><div><Label>Vendor</Label><Select value={form.vendor} onChange={update("vendor")}>{DEVICE_VENDORS.map((item) => <option key={item}>{item}</option>)}</Select></div><div><Label>Model</Label><Input value={form.model ?? ""} onChange={update("model")} /></div><div><Label>Operating system</Label><Input value={form.operatingSystem ?? ""} onChange={update("operatingSystem")} /></div><div><Label>Location</Label><Input value={form.location ?? ""} onChange={update("location")} /></div><div><Label>Serial number</Label><Input value={form.serialNumber ?? ""} onChange={update("serialNumber")} /></div><div className="sm:col-span-2"><Label>Description / notes</Label><Textarea value={form.notes ?? ""} onChange={update("notes")} /></div><label className="flex items-center gap-3 text-sm font-semibold"><input type="checkbox" checked={form.monitoringEnabled === true} onChange={(event) => setForm({ ...form, monitoringEnabled: event.target.checked })} className="size-4 accent-[hsl(var(--primary))]" />Enable automated monitoring</label><div><Label>Polling interval (seconds)</Label><Input type="number" min="30" max="86400" value={form.monitoringIntervalSeconds ?? 60} onChange={(event) => setForm({ ...form, monitoringIntervalSeconds: Number(event.target.value) })} /></div><label className="flex items-center gap-3 text-sm font-semibold sm:col-span-2"><input type="checkbox" checked={form.maintenanceMode === true} onChange={(event) => setForm({ ...form, maintenanceMode: event.target.checked })} className="size-4 accent-[hsl(var(--primary))]" />Maintenance mode <span className="text-xs font-normal text-muted-foreground">Pause automated checks and resolve any open incident.</span></label></div><div className="mt-6 flex justify-end gap-2"><Button type="button" variant="ghost" onClick={onClose}>Cancel</Button><Button type="submit" disabled={saving}>{saving && <Loader2 className="animate-spin" size={14} />}{initial ? "Save changes" : "Add device"}</Button></div></form></Modal>;
}

function Devices() {
  const [items, setItems] = useState<Device[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(false); const [search, setSearch] = useState(""); const [filter, setFilter] = useState("all"); const [sort, setSort] = useState<"hostname" | "status">("hostname"); const [editing, setEditing] = useState<Device>(); const [adding, setAdding] = useState(false);
  const load = () => { setLoading(true); setError(false); api.devices().then(setItems).catch(() => setError(true)).finally(() => setLoading(false)); }; useEffect(load, []);
  const filtered = useMemo(() => items.filter((device) => (filter === "all" || device.lastStatus === filter) && [device.hostname, device.managementIp, device.vendor, device.model, device.location].join(" ").toLowerCase().includes(search.toLowerCase())).sort((a, b) => sort === "hostname" ? a.hostname.localeCompare(b.hostname) : a.lastStatus.localeCompare(b.lastStatus)), [items, search, filter, sort]);
  const remove = (device: Device) => { if (confirm(`Delete ${device.hostname}? This cannot be undone.`)) api.deleteDevice(device.id).then(load).catch(() => undefined); };
  return <><PageTitle eyebrow="Inventory / devices" title="Device inventory" description="The hardware and hosts you care about, recorded with just enough context." action={<Button onClick={() => setAdding(true)}><Plus size={15} />Add device</Button>} /><Card><div className="flex flex-col gap-3 border-b border-card-border p-4 lg:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-3 text-muted-foreground" size={15} /><Input className="pl-9" placeholder="Search hostname, address, vendor..." value={search} onChange={(event) => setSearch(event.target.value)} /></div><div className="flex gap-2"><Select className="w-auto min-w-[130px]" value={filter} onChange={(event) => setFilter(event.target.value)}><option value="all">All statuses</option><option value="online">Online</option><option value="offline">Offline</option><option value="unknown">Unknown</option></Select><Button variant="secondary" onClick={() => setSort(sort === "hostname" ? "status" : "hostname")}><Filter size={14} />{sort === "hostname" ? <ArrowDownAZ size={14} /> : <ArrowUpAZ size={14} />}</Button></div></div>{loading ? <Loading /> : error ? <ErrorState onRetry={load} /> : filtered.length === 0 ? <Empty text={items.length ? "No devices match your filter." : "Your inventory is empty."} action={<Button className="mt-4" onClick={() => setAdding(true)}><Plus size={14} />Add first device</Button>} /> : <div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left"><thead className="bg-secondary/40"><tr className="mono text-[10px] uppercase tracking-wider text-muted-foreground"><th className="px-5 py-3 font-normal">Device</th><th className="px-4 py-3 font-normal">Type / vendor</th><th className="px-4 py-3 font-normal">Location</th><th className="px-4 py-3 font-normal">Status</th><th className="px-5 py-3 text-right font-normal">Actions</th></tr></thead><tbody className="divide-y divide-card-border">{filtered.map((device) => <tr key={device.id} className="group hover:bg-secondary/25"><td className="px-5 py-4"><Link href={`/devices/${device.id}`} className="font-bold hover:text-primary">{device.hostname}</Link><p className="mono mt-1 text-[11px] text-muted-foreground">{device.managementIp}</p></td><td className="px-4 py-4"><p className="text-xs font-semibold">{device.deviceType}</p><p className="mt-1 text-[11px] text-muted-foreground">{device.vendor} {device.model}</p></td><td className="px-4 py-4 text-xs text-muted-foreground">{device.location || "—"}</td><td className="px-4 py-4"><Status status={device.lastStatus} /></td><td className="px-5 py-4"><div className="flex justify-end gap-1 opacity-60 group-hover:opacity-100"><Button variant="ghost" className="p-2" onClick={() => setEditing(device)}><Pencil size={14} /></Button><Button variant="ghost" className="p-2 text-destructive hover:text-destructive" onClick={() => remove(device)}><Trash2 size={14} /></Button></div></td></tr>)}</tbody></table></div>}</Card>{(adding || editing) && <DeviceForm initial={editing} onClose={() => { setAdding(false); setEditing(undefined); }} onSaved={() => { setAdding(false); setEditing(undefined); load(); }} />}</>;
}

function DeviceDetail() {
  const { id } = useParams<{ id: string }>(); const [, setLocation] = useLocation(); const [device, setDevice] = useState<Device>(); const [history, setHistory] = useState<MonitoringHistory[]>([]); const [incidents, setIncidents] = useState<MonitoringIncident[]>([]); const [availability, setAvailability] = useState<AvailabilityWindows>(); const [loading, setLoading] = useState(true); const [pinging, setPinging] = useState(false); const [editing, setEditing] = useState(false);
  const load = () => { if (id) Promise.all([api.device(Number(id)), api.deviceHistory(Number(id)), api.incidents(Number(id)), api.monitoring()]).then(([nextDevice, nextHistory, nextIncidents, monitoring]) => { setDevice(nextDevice); setHistory(nextHistory); setIncidents(nextIncidents); setAvailability(monitoring.deviceAvailability[Number(id)]); }).catch(() => setDevice(undefined)).finally(() => setLoading(false)); }; useEffect(load, [id]);
  if (loading) return <Loading />; if (!device) return <ErrorState onRetry={load} />;
  const ping = () => { setPinging(true); api.pingDevice(device.id).then(load).finally(() => setPinging(false)); };
  const remove = () => { if (confirm(`Delete ${device.hostname}?`)) api.deleteDevice(device.id).then(() => setLocation("/devices")); };
  return <><Link href="/devices" className="mb-6 inline-flex items-center gap-1 text-xs font-bold text-muted-foreground hover:text-foreground"><ChevronLeft size={15} />Back to inventory</Link><PageTitle eyebrow={`Device / ${device.deviceType}`} title={device.hostname} description={`${device.vendor} ${device.model || ""} · ${device.location || "Unassigned location"}`} action={<div className="flex gap-2"><Button variant="secondary" onClick={() => setEditing(true)}><Edit3 size={14} />Edit</Button><Button onClick={ping} disabled={pinging}><Wifi size={14} />{pinging ? "Checking…" : "Ping device"}</Button></div>} /><div className="grid gap-6 lg:grid-cols-[1fr_320px]"><Card className="p-6"><div className="flex items-start justify-between border-b border-card-border pb-5"><div><p className="mono text-[10px] uppercase tracking-wider text-muted-foreground">Reachability</p><div className="mt-3 flex items-center gap-3"><Status status={device.lastStatus} />{device.maintenanceMode && <span className="rounded bg-accent px-2 py-1 text-[10px] font-bold text-accent-foreground">Maintenance</span>}<span className="mono text-xs text-muted-foreground">{device.lastCheckedAt ? new Date(device.lastCheckedAt).toLocaleString() : "Not checked yet"}</span></div></div><div className="grid size-12 place-items-center rounded-full bg-accent text-primary"><Wifi size={21} /></div></div><div className="grid gap-5 pt-6 sm:grid-cols-2"><Detail label="Management IP" value={device.managementIp} mono /><Detail label="Device type" value={device.deviceType} /><Detail label="Operating system" value={device.operatingSystem} /><Detail label="Serial number" value={device.serialNumber} /><Detail label="Monitoring" value={device.maintenanceMode ? "Paused for maintenance" : device.monitoringEnabled ? "Enabled" : "Disabled"} /><Detail label="Record created" value={device.createdAt ? new Date(device.createdAt).toLocaleDateString() : "—"} /></div>{device.notes && <div className="mt-6 border-t border-card-border pt-5"><p className="mono text-[10px] uppercase tracking-wider text-muted-foreground">Notes</p><p className="mt-2 text-sm leading-6 text-muted-foreground">{device.notes}</p></div>}</Card><Card className="h-fit p-5"><p className="mono text-[10px] uppercase tracking-wider text-muted-foreground">Record actions</p><Button variant="danger" className="mt-4 w-full" onClick={remove}><Trash2 size={14} />Delete device</Button><p className="mt-3 text-center text-[11px] leading-5 text-muted-foreground">Deleting removes this record and clears monitoring history and incidents.</p></Card></div><div className="mt-6 grid gap-4 sm:grid-cols-3">{(["24h", "7d", "30d"] as const).map((window) => <AvailabilityCard key={window} label={`${window} availability`} value={availability?.[window]} />)}</div><div className="mt-6 grid gap-6 xl:grid-cols-2"><Card><SectionHeader title="Recent incidents" text="Sustained outages are grouped until recovery." />{incidents.length ? <div className="divide-y divide-card-border">{incidents.slice(0, 10).map((incident) => <IncidentRow key={incident.id} incident={incident} />)}</div> : <Empty text="No incidents recorded for this device." />}</Card><Card><SectionHeader title="Recent checks" text="Automated and manual reachability history." />{history.length ? <div className="divide-y divide-card-border">{history.slice(0, 10).map((item) => <div key={item.id} className="flex items-center justify-between px-5 py-3"><div><Status status={item.status} /><span className="mono ml-3 text-[10px] text-muted-foreground">{item.source}</span></div><div className="mono text-[10px] text-muted-foreground">{new Date(item.checkedAt).toLocaleString()} · {item.latencyMs == null ? "—" : `${item.latencyMs} ms`}</div></div>)}</div> : <Empty text="No checks recorded for this device." />}</Card></div>{editing && <DeviceForm initial={device} onClose={() => setEditing(false)} onSaved={() => { setEditing(false); load(); }} />}</>;
}

type ConfigForm = Record<string, string>;
function generateConfig(vendor: string, type: string, form: ConfigForm): string {
  const user = form.username || "labops-monitor"; const auth = form.authPassword || "<AUTH_PASSWORD>"; const priv = form.privPassword || "<PRIV_PASSWORD>"; const group = form.group || "LABOPS-GROUP"; const access = form.access || "read-only"; const collector = form.collectorIp || "192.168.1.50"; const syslog = form.syslogServer || "192.168.1.50"; const ntp = form.ntpServers || "192.168.1.50"; const port = form.udpPort || "2055"; const source = form.sourceInterface || "Loopback0"; const record = form.recordName || "LABOPS-RECORD"; const exporter = form.exporterName || "LABOPS-EXPORTER"; const monitor = form.monitorName || "LABOPS-MONITOR"; const direction = form.direction || "ingress";
  if (type === "SNMPv3") {
    if (vendor === "Juniper Junos") return `set snmp v3 usm local-engine user ${user} authentication-sha authentication-password ${auth}\nset snmp v3 usm local-engine user ${user} privacy-aes128 privacy-password ${priv}\nset snmp v3 vacm security-to-group security-model usm security-name ${user} group ${group}\nset snmp v3 vacm access group ${group} default-context-prefix security-model usm privacy ${access}`;
    if (vendor === "Arista EOS") return `snmp-server group ${group} v3 ${access}\nsnmp-server user ${user} ${group} v3 auth sha ${auth} priv aes ${priv}`;
    if (vendor === "Cisco NX-OS") return `snmp-server group ${group} v3 ${access}\nsnmp-server user ${user} ${group} auth sha ${auth} priv aes-128 ${priv}`;
    return `snmp-server group ${group} v3 priv\nsnmp-server user ${user} ${group} v3 auth sha ${auth} priv aes 128 ${priv}`;
  }
  if (type === "Syslog") {
    if (vendor === "Juniper Junos") return `set system syslog host ${syslog} any ${form.severity || "info"}\nset system syslog host ${syslog} port ${form.udpPort || "514"}\n${source ? `set system syslog host ${syslog} source-address ${source}` : ""}`;
    return `logging host ${syslog} transport udp port ${form.udpPort || "514"}\nlogging trap ${form.severity || "informational"}\n${source ? `logging source-interface ${source}` : ""}`;
  }
  if (type === "NTP") {
    const lines = ntp.split(",").map((server) => server.trim()).filter(Boolean);
    if (vendor === "Juniper Junos") return lines.map((server) => `set system ntp server ${server}`).concat(source ? [`set system ntp source-address ${source}`] : []).join("\n");
    return lines.map((server) => `ntp server ${server}`).concat(source ? [`ntp source ${source}`] : []).join("\n");
  }
  if (vendor === "Juniper Junos") return `set services flow-monitoring version-ipfix template ${monitor}\nset forwarding-options sampling instance ${monitor} input rate 1\nset forwarding-options sampling instance ${monitor} family inet output flow-server ${collector} port ${port}\nset forwarding-options sampling instance ${monitor} family inet output flow-server ${collector} source-address ${source}`;
  if (vendor === "Arista EOS") return `flow record ${record}\n  match ipv4 source address\n  match ipv4 destination address\nflow exporter ${exporter}\n  destination ${collector}\n  transport udp ${port}\nflow monitor ${monitor}\n  record ${record}\n  exporter ${exporter}\ninterface ${source}\n  ip flow monitor ${monitor} ${direction}`;
  const interfaceDirection = direction === "ingress" ? "input" : "output";
  return `flow record ${record}\n match ipv4 source address\n match ipv4 destination address\n match transport source-port\n match transport destination-port\n match ip protocol\n collect counter bytes long\n collect counter packets long\n collect timestamp absolute first\n collect timestamp absolute last\n!\nflow exporter ${exporter}\n destination ${collector}\n source ${source}\n transport udp ${port}\n export-protocol netflow-v9\n!\nflow monitor ${monitor}\n exporter ${exporter}\n record ${record}\n!\ninterface ${source}\n ip flow monitor ${monitor} ${interfaceDirection}`;
}
function configExplanation(type: string): { title: string; text: string }[] {
  if (type === "SNMPv3") return [{ title: "Identity", text: "Creates the SNMPv3 user and group." }, { title: "Security", text: "Applies authentication and privacy settings." }, { title: "Access", text: "Limits the user to the selected read-only or read-write scope." }];
  if (type === "Syslog") return [{ title: "Destination", text: "Sends device messages to the selected syslog server." }, { title: "Severity", text: "Sets the minimum event severity to forward." }, { title: "Source", text: "Optionally pins messages to a management interface." }];
  if (type === "NTP") return [{ title: "Servers", text: "Adds the requested time sources." }, { title: "Clock", text: "Keeps logs and status checks aligned to a reliable time source." }, { title: "Source", text: "Optionally chooses the interface used for NTP traffic." }];
  return [{ title: "Record", text: "Defines the fields collected for each flow." }, { title: "Exporter", text: "Sends IPFIX or NetFlow records to the collector." }, { title: "Monitor", text: "Attaches the monitor to ingress or egress traffic." }];
}
function ConfigGenerator() {
  const [vendor, setVendor] = useState(CONFIG_VENDORS[0]); const [type, setType] = useState(CONFIG_TYPES[0]); const [form, setForm] = useState<ConfigForm>({ username: "labops-monitor", authProtocol: "SHA", authPassword: "", privacyProtocol: "AES-128", privPassword: "", group: "LABOPS-GROUP", access: "read-only", syslogServer: "192.168.1.50", severity: "informational", ntpServers: "192.168.1.50", collectorIp: "192.168.1.50", udpPort: "2055", sourceInterface: "Loopback0", monitorName: "LABOPS-MONITOR", recordName: "LABOPS-RECORD", exporterName: "LABOPS-EXPORTER", direction: "ingress" }); const [devices, setDevices] = useState<Device[]>([]); const [showSave, setShowSave] = useState(false); const [saved, setSaved] = useState(false); const [name, setName] = useState(""); const [notes, setNotes] = useState(""); const [associatedDeviceId, setAssociatedDeviceId] = useState("");
  const config = useMemo(() => generateConfig(vendor, type, form), [vendor, type, form]); const update = (key: string) => (event: ChangeEvent<HTMLInputElement | HTMLSelectElement>) => setForm({ ...form, [key]: key === "access" && vendor === "Cisco IOS / IOS-XE" && type === "SNMPv3" ? "read-only" : event.target.value }); useEffect(() => { Promise.all([api.devices(), api.settings()]).then(([nextDevices, settings]) => { setDevices(nextDevices); if (CONFIG_VENDORS.includes(settings.defaultConfigVendor)) setVendor(settings.defaultConfigVendor); }).catch(() => undefined); }, []);
  const clear = () => setForm({ username: "", authProtocol: "SHA", authPassword: "", privacyProtocol: "AES-128", privPassword: "", group: "", access: "read-only", syslogServer: "", severity: "informational", ntpServers: "", collectorIp: "", udpPort: "", sourceInterface: "", monitorName: "", recordName: "", exporterName: "", direction: "ingress" });
  const save = () => { api.saveConfig({ name: name || `${vendor} ${type}`, vendor, configurationType: type, associatedDeviceId: associatedDeviceId ? Number(associatedDeviceId) : undefined, generatedConfiguration: config, notes, authPassword: form.authPassword, privacyPassword: form.privPassword }).then(() => { setShowSave(false); setSaved(true); setName(""); setNotes(""); setTimeout(() => setSaved(false), 2500); }).catch(() => undefined); };
  const isSnmp = type === "SNMPv3"; const isSyslog = type === "Syslog"; const isNtp = type === "NTP"; const isCiscoIosSnmp = vendor === "Cisco IOS / IOS-XE" && isSnmp; useEffect(() => { document.querySelectorAll('select option[value="read-write"]').forEach((option) => { (option as HTMLOptionElement).disabled = isCiscoIosSnmp; }); }, [isCiscoIosSnmp]);
  return <><PageTitle eyebrow="Build / configuration" title="Configuration generator" description="Generate a clean starting point for SNMPv3, syslog, NTP, and flow export." action={<Link href="/config-generator/saved" className="inline-flex items-center gap-2 text-xs font-bold text-primary hover:underline"><Clipboard size={14} />Saved configurations</Link>} /><div className="grid gap-6 xl:grid-cols-[380px_1fr]"><Card className="p-5"><div className="mb-5"><p className="mono text-[10px] uppercase tracking-wider text-muted-foreground">01 / Parameters</p><h2 className="mt-2 font-bold">Choose a platform</h2></div><div className="space-y-4"><div><Label>Vendor</Label><Select value={vendor} onChange={(event) => setVendor(event.target.value)}>{CONFIG_VENDORS.map((item) => <option key={item}>{item}</option>)}</Select></div><div><Label>Configuration type</Label><Select value={type} onChange={(event) => setType(event.target.value)}>{CONFIG_TYPES.map((item) => <option key={item}>{item}</option>)}</Select></div>{isSnmp && <><div><Label>Username</Label><Input value={form.username} onChange={update("username")} /></div><div><Label>Authentication protocol</Label><Select value={form.authProtocol} onChange={update("authProtocol")}><option>SHA</option><option>MD5</option></Select></div><div><Label>Authentication password</Label><Input type="password" value={form.authPassword} onChange={update("authPassword")} placeholder="Used only for this generation" /></div><div><Label>Privacy protocol</Label><Select value={form.privacyProtocol} onChange={update("privacyProtocol")}><option>AES-128</option><option>DES</option></Select></div><div><Label>Privacy password</Label><Input type="password" value={form.privPassword} onChange={update("privPassword")} placeholder="Used only for this generation" /></div><div><Label>SNMP group</Label><Input value={form.group} onChange={update("group")} /></div><div><Label>Access</Label><Select value={form.access} onChange={update("access")}><option value="read-only">Read-only</option><option value="read-write">Read-write</option></Select></div></>}{isSyslog && <><div><Label>Syslog server</Label><Input className="mono" value={form.syslogServer} onChange={update("syslogServer")} /></div><div><Label>UDP port</Label><Input className="mono" value={form.udpPort === "2055" ? "514" : form.udpPort} onChange={update("udpPort")} /></div><div><Label>Severity</Label><Select value={form.severity} onChange={update("severity")}><option>informational</option><option>warning</option><option>errors</option></Select></div><div><Label>Source interface (optional)</Label><Input value={form.sourceInterface} onChange={update("sourceInterface")} /></div></>}{isNtp && <><div><Label>NTP servers</Label><Input className="mono" value={form.ntpServers} onChange={update("ntpServers")} placeholder="192.168.1.50, 192.168.1.51" /></div><div><Label>Source interface (optional)</Label><Input value={form.sourceInterface} onChange={update("sourceInterface")} /></div></>}{!isSnmp && !isSyslog && !isNtp && <><div><Label>Collector IP</Label><Input className="mono" value={form.collectorIp} onChange={update("collectorIp")} /></div><div><Label>UDP port</Label><Input className="mono" value={form.udpPort} onChange={update("udpPort")} /></div><div><Label>Source interface</Label><Input value={form.sourceInterface} onChange={update("sourceInterface")} /></div><div className="grid grid-cols-2 gap-3"><div><Label>Flow monitor</Label><Input value={form.monitorName} onChange={update("monitorName")} /></div><div><Label>Flow record</Label><Input value={form.recordName} onChange={update("recordName")} /></div></div><div className="grid grid-cols-2 gap-3"><div><Label>Flow exporter</Label><Input value={form.exporterName} onChange={update("exporterName")} /></div><div><Label>Direction</Label><Select value={form.direction} onChange={update("direction")}><option>ingress</option><option>egress</option></Select></div></div></>}</div></Card><div className="space-y-6"><Card className="overflow-hidden"><div className="flex items-center justify-between border-b border-card-border bg-secondary/30 px-5 py-4"><div><p className="mono text-[10px] uppercase tracking-wider text-primary">02 / Output</p><h2 className="mt-1 font-bold">{vendor}</h2></div><Button variant="secondary" onClick={() => navigator.clipboard?.writeText(config)}><Copy size={14} />Copy configuration</Button></div><pre className="lab-grid min-h-[300px] overflow-auto p-5 text-[12px] leading-7 text-foreground"><code>{config}</code></pre><div className="flex flex-wrap items-center justify-between gap-3 border-t border-card-border px-5 py-4"><p className="text-xs text-muted-foreground">{isSnmp ? "Passwords are never stored. Saved output uses placeholders." : "Review before applying to production hardware."}</p><div className="flex gap-2"><Button variant="ghost" onClick={clear}><X size={14} />Clear</Button><Button onClick={() => setShowSave(true)}><Database size={14} />Save configuration</Button></div></div></Card><Card className="p-5"><p className="mono text-[10px] uppercase tracking-wider text-muted-foreground">What this configuration does</p><div className="mt-4 grid gap-4 sm:grid-cols-3">{configExplanation(type).map((item) => <Explanation key={item.title} title={item.title} text={item.text} />)}</div></Card></div></div>{showSave && <Modal onClose={() => setShowSave(false)}><div className="flex justify-between"><h2 className="font-bold">Save configuration</h2><Button variant="ghost" onClick={() => setShowSave(false)}><X size={17} /></Button></div><div className="mt-5 space-y-4"><div><Label>Name</Label><Input value={name} onChange={(event) => setName(event.target.value)} placeholder="Monitoring baseline" /></div><div><Label>Associate device</Label><Select value={associatedDeviceId} onChange={(event) => setAssociatedDeviceId(event.target.value)}><option value="">No associated device</option>{devices.map((device) => <option value={device.id} key={device.id}>{device.hostname}</option>)}</Select></div><div><Label>Notes</Label><Textarea value={notes} onChange={(event) => setNotes(event.target.value)} /></div>{isSnmp && <p className="rounded-md border border-primary/20 bg-primary/5 p-3 text-xs leading-5 text-muted-foreground">Authentication and privacy passwords will be replaced with <code>&lt;AUTH_PASSWORD&gt;</code> and <code>&lt;PRIV_PASSWORD&gt;</code> before saving.</p>}</div><div className="mt-6 flex justify-end gap-2"><Button variant="ghost" onClick={() => setShowSave(false)}>Cancel</Button><Button onClick={save}>Save record</Button></div></Modal>}{saved && <div className="fixed bottom-5 right-5 z-50 flex items-center gap-2 rounded-md border border-primary/30 bg-card px-4 py-3 text-sm shadow-xl"><Check className="text-primary" size={16} />Saved configuration</div>}</>;
}
function Explanation({ title, text }: { title: string; text: string }) { return <div><p className="text-xs font-bold">{title}</p><p className="mt-1 text-xs leading-5 text-muted-foreground">{text}</p></div>; }

function SavedConfigs() {
  const [items, setItems] = useState<SavedConfiguration[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(false); const [, setLocation] = useLocation(); const load = () => api.saved().then(setItems).catch(() => setError(true)).finally(() => setLoading(false)); useEffect(() => { void load(); }, []);
  const remove = (item: SavedConfiguration) => { if (confirm(`Delete ${item.name}?`)) api.deleteConfig(item.id).then(load).catch(() => undefined); };
  return <><PageTitle eyebrow="Utilities / archive" title="Saved configurations" description="Reusable output kept close to the hardware it was made for." action={<Link href="/config-generator" className="inline-flex items-center gap-2 rounded-md bg-primary px-3.5 py-2 text-xs font-bold text-primary-foreground"><Plus size={14} />New configuration</Link>} /><Card>{loading ? <Loading /> : error ? <ErrorState onRetry={load} /> : items.length === 0 ? <Empty text="No saved configurations yet." action={<Button className="mt-4" onClick={() => setLocation("/config-generator")}><Plus size={14} />Generate one</Button>} /> : <div className="divide-y divide-card-border">{items.map((item) => <div key={item.id} className="flex flex-col gap-4 p-5 sm:flex-row sm:items-center sm:justify-between"><div><div className="flex items-center gap-3"><h3 className="font-bold">{item.name}</h3><span className="rounded bg-accent px-2 py-1 text-[10px] font-bold text-accent-foreground">{item.vendor}</span></div><p className="mono mt-2 text-[11px] text-muted-foreground">{item.configurationType} · {item.createdAt ? new Date(item.createdAt).toLocaleDateString() : "—"}</p>{item.notes && <p className="mt-2 text-xs text-muted-foreground">{item.notes}</p>}</div><div className="flex gap-2"><Button variant="secondary" onClick={() => navigator.clipboard?.writeText(item.generatedConfiguration)}><Copy size={14} />Copy</Button><Button variant="danger" onClick={() => remove(item)}><Trash2 size={14} /></Button></div></div>)}</div>}</Card></>;
}

function Monitoring() {
  const [devices, setDevices] = useState<Device[]>([]); const [incidents, setIncidents] = useState<MonitoringIncident[]>([]); const [availability, setAvailability] = useState<AvailabilityWindows>(); const [incidentFilter, setIncidentFilter] = useState("all"); const [loading, setLoading] = useState(true); const [error, setError] = useState(false);
  const load = () => { setLoading(true); setError(false); api.monitoring().then((data) => { setDevices(data.devices); setIncidents(data.incidents); setAvailability(data.availability); }).catch(() => setError(true)).finally(() => setLoading(false)); };
  useEffect(() => { void load(); const timer = window.setInterval(load, 30000); return () => window.clearInterval(timer); }, []);
  const names = new Map(devices.map((device) => [device.id, device.hostname]));
  const filteredIncidents = incidents.filter((incident) => incidentFilter === "all" || incident.status === incidentFilter);
  return <><PageTitle eyebrow="Operations / monitoring" title="Monitoring" description="Availability, sustained outage incidents, and current health for inventory devices." action={<Button variant="secondary" onClick={load}><RefreshCw size={14} />Refresh</Button>} />{error ? <ErrorState onRetry={load} /> : loading ? <Loading /> : <div className="space-y-6"><div className="grid gap-4 sm:grid-cols-3">{(["24h", "7d", "30d"] as const).map((window) => <AvailabilityCard key={window} label={`${window} fleet availability`} value={availability?.[window]} />)}</div><Card><div className="overflow-x-auto"><table className="w-full min-w-[900px] text-left"><thead className="bg-secondary/40"><tr className="mono text-[10px] uppercase tracking-wider text-muted-foreground"><th className="px-5 py-3 font-normal">Device</th><th className="px-4 py-3 font-normal">Status</th><th className="px-4 py-3 font-normal">Last checked</th><th className="px-4 py-3 font-normal">Latency</th><th className="px-4 py-3 font-normal">Failures</th><th className="px-5 py-3 font-normal">Interval</th></tr></thead><tbody className="divide-y divide-card-border">{devices.map((device) => <tr key={device.id}><td className="px-5 py-4"><Link href={`/devices/${device.id}`} className="font-bold hover:text-primary">{device.hostname}</Link><p className="mono mt-1 text-[11px] text-muted-foreground">{device.maintenanceMode ? "maintenance" : device.monitoringEnabled ? "enabled" : "disabled"}</p></td><td className="px-4 py-4"><Status status={device.lastStatus} /></td><td className="px-4 py-4 text-xs text-muted-foreground">{device.lastCheckedAt ? new Date(device.lastCheckedAt).toLocaleString() : "Not checked"}</td><td className="mono px-4 py-4 text-xs">{device.lastLatencyMs != null ? `${device.lastLatencyMs} ms` : "—"}</td><td className="mono px-4 py-4 text-xs">{device.consecutiveFailures}</td><td className="mono px-5 py-4 text-xs">{device.monitoringIntervalSeconds}s</td></tr>)}</tbody></table></div></Card><Card><div className="flex flex-col gap-3 border-b border-card-border px-5 py-4 sm:flex-row sm:items-center sm:justify-between"><div><h2 className="font-bold">Outage incidents</h2><p className="mt-1 text-xs text-muted-foreground">Repeated failed polls are grouped into one incident through recovery.</p></div><Select className="w-auto" value={incidentFilter} onChange={(event) => setIncidentFilter(event.target.value)}><option value="all">All incidents</option><option value="open">Open</option><option value="resolved">Resolved</option></Select></div>{filteredIncidents.length ? <div className="divide-y divide-card-border">{filteredIncidents.slice(0, 50).map((incident) => <IncidentRow key={incident.id} incident={incident} deviceName={names.get(incident.deviceId) ?? `Device ${incident.deviceId}`} />)}</div> : <Empty text="No incidents match this filter." />}</Card></div>}</>;
}

function Tools() { return <><PageTitle eyebrow="Utilities / network" title="Network tools" description="Small, practical calculators for the work between tickets." /><div className="grid gap-4 md:grid-cols-2"><ToolCard href="/tools/subnet" title="Subnet calculator" description="Break down an IPv4 CIDR into network, broadcast, host range, and count." icon={Calculator} /><ToolCard href="/tools/ping" title="Manual ping" description="Check reachability from the LabOps host with an explicit timeout." icon={Wifi} /></div></>; }
function ToolCard({ href, title, description, icon: Icon }: { href: string; title: string; description: string; icon: typeof Calculator }) { return <Link href={href} className="group rounded-lg border border-card-border bg-card p-6 transition-colors hover:border-primary/50 hover:bg-accent/30"><div className="mb-9 grid size-10 place-items-center rounded-md bg-accent text-primary"><Icon size={19} /></div><h2 className="text-lg font-extrabold">{title}</h2><p className="mt-2 max-w-sm text-sm leading-6 text-muted-foreground">{description}</p><span className="mt-7 inline-flex items-center gap-2 text-xs font-bold text-primary">Open tool <ChevronRight size={14} className="transition-transform group-hover:translate-x-1" /></span></Link>; }
function calculateSubnet(input: string): Record<string, string> { const match = input.trim().match(/^(\d{1,3}(?:\.\d{1,3}){3})\/(\d{1,2})$/); if (!match) return { error: "Enter a valid CIDR, for example 192.168.10.0/24." }; const nums = match[1].split(".").map(Number); const prefix = Number(match[2]); if (nums.some((number) => number > 255) || prefix > 32) return { error: "That address or prefix is not valid." }; const ip = nums.reduce((value, number) => (value << 8) + number, 0) >>> 0; const mask = prefix === 0 ? 0 : (0xffffffff << (32 - prefix)) >>> 0; const network = (ip & mask) >>> 0; const broadcast = (network + (~mask >>> 0)) >>> 0; const fmt = (value: number) => [value >>> 24, (value >>> 16) & 255, (value >>> 8) & 255, value & 255].join("."); const hosts = Math.max(0, 2 ** (32 - prefix) - (prefix >= 31 ? 0 : 2)); return { network_address: fmt(network), broadcast_address: fmt(broadcast), first_host: fmt(prefix >= 31 ? network : network + 1), last_host: fmt(prefix >= 31 ? broadcast : broadcast - 1), usable_hosts: hosts.toLocaleString(), subnet_mask: fmt(mask) }; }
function Subnet() { const [cidr, setCidr] = useState("192.168.10.0/24"); const result = useMemo(() => calculateSubnet(cidr), [cidr]); return <><PageTitle eyebrow="Tools / ipv4" title="Subnet calculator" description="A quick read of the boundaries inside an IPv4 network." /><Card className="max-w-3xl p-6"><Label>IPv4 address / CIDR prefix</Label><div className="flex gap-2"><Input value={cidr} onChange={(event) => setCidr(event.target.value)} className="mono" /><Button variant="secondary" onClick={() => setCidr("10.0.0.0/8")}>/8</Button><Button variant="secondary" onClick={() => setCidr("172.16.0.0/16")}>/16</Button></div>{result.error ? <p className="mt-4 text-sm text-destructive">{result.error}</p> : <div className="mt-7 grid gap-3 sm:grid-cols-2">{Object.entries(result).map(([key, value]) => <div className="rounded-md border border-border bg-secondary/30 p-4" key={key}><p className="text-[11px] capitalize text-muted-foreground">{key.replaceAll("_", " ")}</p><p className="mono mt-2 text-sm font-medium">{value}</p></div>)}</div>}</Card></>; }
function PingTool() { const [target, setTarget] = useState("192.168.1.1"); const [result, setResult] = useState<PingResult>(); const [loading, setLoading] = useState(false); const run = () => { setLoading(true); setResult(undefined); api.ping({ target }).then(setResult).catch(() => setResult({ status: "unknown", latencyMs: null, message: "LabOps could not perform this check." })).finally(() => setLoading(false)); }; return <><PageTitle eyebrow="Tools / reachability" title="Manual ping" description="One explicit check, from this workspace to a host you name." /><div className="grid gap-6 lg:grid-cols-[380px_1fr]"><Card className="p-6"><Label>Hostname or IP address</Label><Input value={target} onChange={(event) => setTarget(event.target.value)} className="mono" placeholder="192.168.1.1" /><Button className="mt-6 w-full" onClick={run} disabled={loading || !target}>{loading ? <Loader2 className="animate-spin" size={15} /> : <Wifi size={15} />}{loading ? "Checking…" : "Run ping"}</Button></Card><Card className="min-h-[250px] p-6">{!result && !loading ? <div className="grid h-full min-h-[200px] place-items-center text-center text-sm text-muted-foreground"><div><Wifi className="mx-auto mb-3 text-muted-foreground" size={23} /><p>Results will appear here</p><p className="mt-1 text-xs">No request is sent until you run the check.</p></div></div> : loading ? <Loading /> : <div><div className="flex items-center gap-3"><Status status={result?.status} /><span className="mono text-xs">{target}</span></div><p className="mt-5 text-sm leading-6 text-muted-foreground">{result?.message}</p><div className="mt-7 grid gap-3 sm:grid-cols-2"><Detail label="Latency" value={result?.latencyMs != null ? `${result.latencyMs} ms` : "—"} mono /><Detail label="Checked at" value={new Date().toLocaleTimeString()} /></div></div>}</Card></div></>; }

function SettingsPage() {
  const [settings, setSettings] = useState<Settings>({ applicationName: "LabOps", defaultTheme: "dark", defaultConfigVendor: CONFIG_VENDORS[0], pingTimeoutSeconds: 3, webhookEnabled: false, webhookUrl: "" });
  const [deliveries, setDeliveries] = useState<NotificationDelivery[]>([]); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [testing, setTesting] = useState(false); const [message, setMessage] = useState("");
  const [retryingDeliveryId, setRetryingDeliveryId] = useState<number>();
  const loadDeliveries = () => api.notificationDeliveries().then(setDeliveries).catch(() => undefined);
  useEffect(() => { Promise.all([api.settings().then(setSettings), loadDeliveries()]).finally(() => setLoading(false)); }, []);
  useEffect(() => { document.documentElement.classList.toggle("dark", settings.defaultTheme !== "light"); }, [settings.defaultTheme]);
  const update = (key: keyof Settings) => (event: ChangeEvent<HTMLInputElement | HTMLSelectElement>) => setSettings({ ...settings, [key]: key === "pingTimeoutSeconds" ? Number(event.target.value) : event.target.value });
  const save = () => { setSaving(true); api.updateSettings(settings).then(setSettings).then(() => setMessage("Settings saved")).catch((error) => setMessage(error instanceof Error ? error.message : "Unable to save settings")).finally(() => setSaving(false)); };
  const testWebhook = () => { setTesting(true); api.updateSettings(settings).then(setSettings).then(() => api.testWebhook()).then((delivery) => setMessage(delivery.status === "delivered" ? "Test webhook delivered" : "Test failed; automatic retry scheduled")).catch(() => setMessage("Unable to test webhook; review delivery history")).finally(() => { setTesting(false); void loadDeliveries(); }); };
  const retryWebhook = (id: number) => { setRetryingDeliveryId(id); api.retryWebhook(id).then((delivery) => setMessage(delivery.status === "delivered" ? "Webhook delivered" : "Retry scheduled")).catch((error) => setMessage(error instanceof Error ? error.message : "Unable to retry webhook")).finally(() => { setRetryingDeliveryId(undefined); void loadDeliveries(); }); };
  if (loading) return <Loading />;
  return <><PageTitle eyebrow="Workspace / preferences" title="Settings" description="Application defaults and reliable incident notifications." /><div className="max-w-3xl space-y-6"><Card className="p-6"><div className="mb-6 border-b border-card-border pb-5"><p className="font-bold">Application</p><p className="mt-1 text-xs text-muted-foreground">Name and appearance for this workspace.</p></div><div className="space-y-5"><div><Label>Application name</Label><Input value={settings.applicationName} onChange={update("applicationName")} /></div><div><Label>Default theme</Label><div className="grid grid-cols-2 gap-2"><button onClick={() => setSettings({ ...settings, defaultTheme: "dark" })} className={cls("rounded-md border p-3 text-left text-xs font-bold", settings.defaultTheme !== "light" ? "border-primary bg-accent text-accent-foreground" : "border-border text-muted-foreground")}>Dark / console</button><button onClick={() => setSettings({ ...settings, defaultTheme: "light" })} className={cls("rounded-md border p-3 text-left text-xs font-bold", settings.defaultTheme === "light" ? "border-primary bg-accent text-accent-foreground" : "border-border text-muted-foreground")}>Light / daylight</button></div></div></div></Card><Card className="p-6"><div className="mb-6 border-b border-card-border pb-5"><p className="font-bold">Operational defaults</p><p className="mt-1 text-xs text-muted-foreground">Used in the generator and manual reachability checks.</p></div><div className="grid gap-5 sm:grid-cols-2"><div><Label>Default generator vendor</Label><Select value={settings.defaultConfigVendor} onChange={update("defaultConfigVendor")}>{CONFIG_VENDORS.map((item) => <option key={item}>{item}</option>)}</Select></div><div><Label>Ping timeout (seconds)</Label><Input type="number" min="1" max="30" value={settings.pingTimeoutSeconds} onChange={update("pingTimeoutSeconds")} /></div></div></Card><Card><SectionHeader title="Incident webhook" text="Send JSON events when sustained outages open or recover. Failed deliveries retry twice with bounded backoff." /><div className="space-y-4 p-6"><label className="flex items-center gap-3 text-sm font-semibold"><input type="checkbox" checked={settings.webhookEnabled} onChange={(event) => setSettings({ ...settings, webhookEnabled: event.target.checked })} className="size-4 accent-[hsl(var(--primary))]" />Enable incident webhook</label><div><Label>Webhook URL</Label><Input type="url" placeholder="https://hooks.example.com/labops" value={settings.webhookUrl} onChange={update("webhookUrl")} /></div><div className="flex justify-end"><Button variant="secondary" onClick={testWebhook} disabled={testing || !settings.webhookEnabled || !settings.webhookUrl}>{testing && <Loader2 size={14} className="animate-spin" />}Send test webhook</Button></div></div></Card><Card><SectionHeader title="Recent webhook deliveries" text="Durable delivery state, attempts, next retry, and operator controls." />{deliveries.length ? <div className="divide-y divide-card-border">{deliveries.slice(0, 10).map((delivery) => <div key={delivery.id} className="flex flex-col gap-3 px-5 py-4 sm:flex-row sm:items-center sm:justify-between"><div><span className={cls("text-xs font-bold", delivery.status === "delivered" ? "text-primary" : delivery.status === "retrying" ? "text-amber-400" : "text-destructive")}>{delivery.status}</span><span className="mono ml-3 text-[10px] text-muted-foreground">{delivery.eventType} · attempt {delivery.attemptCount}/3</span><p className="mt-1 text-xs text-muted-foreground">{delivery.status === "retrying" && delivery.nextAttemptAt ? `Next retry ${new Date(delivery.nextAttemptAt).toLocaleString()}` : delivery.errorMessage || `HTTP ${delivery.responseStatus ?? "—"}`}</p></div><div className="flex items-center gap-3"><span className="mono text-[10px] text-muted-foreground">{new Date(delivery.attemptedAt).toLocaleString()}</span>{delivery.status !== "delivered" && <Button variant="ghost" onClick={() => retryWebhook(delivery.id)} disabled={retryingDeliveryId === delivery.id}>{retryingDeliveryId === delivery.id ? <Loader2 size={13} className="animate-spin" /> : <RefreshCw size={13} />}Retry now</Button>}</div></div>)}</div> : <Empty text="No webhook deliveries yet." />}</Card><div className="flex items-center justify-end gap-3"><span className="text-xs text-primary">{message}</span><Button onClick={save} disabled={saving}>{saving && <Loader2 size={14} className="animate-spin" />}Save settings</Button></div></div></>;
}

function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><Layout><ErrorBoundary><Switch><Route path="/" component={Dashboard} /><Route path="/devices" component={Devices} /><Route path="/devices/:id" component={DeviceDetail} /><Route path="/monitoring" component={Monitoring} /><Route path="/config-generator/saved" component={SavedConfigs} /><Route path="/config-generator" component={ConfigGenerator} /><Route path="/tools/subnet" component={Subnet} /><Route path="/tools/ping" component={PingTool} /><Route path="/tools" component={Tools} /><Route path="/settings" component={SettingsPage} /><Route component={NotFound} /></Switch></ErrorBoundary></Layout><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;
